import{_ as a,a as i,c as t,ac as r}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"英语：句子、时间与信息","description":"从明确前置到具体题目、参考解答及适用边界。英语：句子、时间与信息","frontmatter":{"title":"英语：句子、时间与信息","description":"从明确前置到具体题目、参考解答及适用边界。英语：句子、时间与信息","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"英语：从能力自测到表达","summary":"从明确前置到具体题目、参考解答及适用边界。英语：句子、时间与信息","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"英语：从能力自测到表达","link":"/life/english/reference/pathway"},"next":{"text":"英语：借阅沟通完整练习","link":"/life/english/practice/workshop"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"英语：从能力自测到表达","link":"/life/english/reference/pathway"},"next":{"text":"英语：借阅沟通完整练习","link":"/life/english/practice/workshop"}},"headers":[],"relativePath":"life/english/foundations/language.md","filePath":"life/english/foundations/language.md"}'),n={name:"life/english/foundations/language.md"};function l(o,e,s,d,h,c){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="英语-句子、时间与信息" tabindex="-1">英语：句子、时间与信息 <a class="header-anchor" href="#英语-句子、时间与信息" aria-label="Permalink to &quot;英语：句子、时间与信息&quot;">​</a></h1><p>本课按实际能力与证据阅读；以下例子为原创教学材料，不代表用户事实。</p><h2 id="skeleton" tabindex="-1">句子骨架 <a class="header-anchor" href="#skeleton" aria-label="Permalink to &quot;句子骨架 {#skeleton}&quot;">​</a></h2><p>英语 句子骨架先找主语和限定动词，再找宾语、补语与修饰语。“The quiet student reads a book after lunch.” 中 student 是主语中心，reads 是谓语动词，a book 是宾语，after lunch 是时间状语。quiet 是形容词，不能因为它靠近主语就当成谓语。</p><p>题：分析 “The room is quiet.”。答案：The room 为主语，is 为系动词，quiet 为主语补语；没有动作承受者，所以不硬填宾语。“Reading slowly, Mei checked the date.” 开头是与主句共享主语的分词短语，不是带独立逻辑主语的独立主格，也不是倒装。</p><h2 id="time" tabindex="-1">时间与体 <a class="header-anchor" href="#time" aria-label="Permalink to &quot;时间与体 {#time}&quot;">​</a></h2><p>英语 时间与体需要区分习惯、完成事件与正在发生。一般现在时 “Mei reads every evening.” 描述习惯；一般过去时 “Mei read yesterday.” 指明过去事件；现在进行时 “Mei is reading now.” 强调当前过程。read 的现在式与过去式拼写相同，读音不同，本页不提供声音验证。</p><p>题：①She ___ (visit) the library yesterday. ②She ___ (read) now. ③She ___ (finish) two books so far. 答案①visited；②is reading；③has finished。so far 把参照点连到现在，当前语境用现在完成时；不能以“有时间词”就一概选择过去时。</p><h2 id="voice" tabindex="-1">语态与衔接 <a class="header-anchor" href="#voice" aria-label="Permalink to &quot;语态与衔接 {#voice}&quot;">​</a></h2><p>英语 语态与衔接先决定强调谁，再保持原时态。“Mei returned the book.” 改成 “The book was returned by Mei.”，returned 的过去事件保留，was 加过去分词构成被动。进行时不是第三种语态；“Mei was returning the book.”仍是主动。</p><p>题：合并 “It rained. Mei went to the library.” 表达让步。参考：“Although it rained, Mei went to the library.” although 后已有从属关系，不再加 but 连接同一主句。句子 “It rained, and Mei stayed home.” 是并列句；“Mei stayed home because it rained.” 是含原因从句的复合句。根据想表达的关系选择连接词，不能只按句子长短分类。</p>',11)])])}const u=a(n,[["render",l]]);export{p as __pageData,u as default};
